//! Renderer fixtures for architecture diagrams, generated by
//! `research/mermaid-port/harness/generate-architecture-render-fixtures.mjs` from upstream
//! mermaid under jsdom. The expected geometry is read back from the SVG that
//! `architectureRenderer.ts` draws; see the generator's header for the two measurement
//! patches (cytoscape's canvas labels and the `<text>` bounding box) that make the fixture
//! measure the way a browser does under the monospace rule.
//!
//! The scene is compared geometrically: every service and junction placement, every group
//! rectangle and label, every edge path point, arrow polygon and label, every icon primitive,
//! and the fitted viewBox, all within 0.01px.

use serde_json::Value;

use crate::config::Config;
use crate::measure::FallbackMeasure;
use crate::scene::{Group, Item, PathShape, Scene, TextAnchor, TextRun, Transform};

use crate::diagrams::architecture::render;
use crate::diagrams::architecture::render::ArchitectureRenderError;

const TOLERANCE: f64 = 0.01;

fn fixtures() -> Vec<(String, Value)> {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("src/diagrams/architecture/tests/render");
    let mut fixtures: Vec<(String, Value)> = std::fs::read_dir(&dir)
        .unwrap_or_else(|error| panic!("read {}: {error}", dir.display()))
        .map(|entry| entry.expect("dir entry").path())
        .filter(|path| path.extension().and_then(|extension| extension.to_str()) == Some("json"))
        .map(|path| {
            let text = std::fs::read_to_string(&path).expect("read fixture");
            let value: Value = serde_json::from_str(&text).expect("parse fixture");
            (
                path.file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or_default()
                    .to_string(),
                value,
            )
        })
        .collect();
    fixtures.sort_by(|a, b| a.0.cmp(&b.0));
    fixtures
}

fn config_for(source: &str) -> Config {
    let preprocessed = crate::preprocess::preprocess(source);
    let mut config = Config::default();
    config
        .apply(&preprocessed.config)
        .unwrap_or_else(|error| panic!("config: {error}"));
    config
}

fn close(actual: f64, expected: f64, what: &str, file: &str) {
    assert!(
        (actual - expected).abs() <= TOLERANCE,
        "{file}: {what}: actual {actual} vs expected {expected}"
    );
}

fn number(value: &Value, key: &str) -> f64 {
    value[key]
        .as_f64()
        .unwrap_or_else(|| panic!("expected a number at {key}: {value}"))
}

#[derive(Clone, Debug)]
struct DrawnText {
    text: String,
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    baseline: f64,
    anchor: &'static str,
    rotation: f64,
}

fn collapse(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn run_text(run: &TextRun) -> String {
    collapse(&run.lines.iter().map(|line| line.text()).collect::<String>())
}

fn anchor_name(anchor: TextAnchor) -> &'static str {
    match anchor {
        TextAnchor::Start => "start",
        TextAnchor::Middle => "middle",
        TextAnchor::End => "end",
    }
}

fn text_runs(item: &Item, transform: Transform, out: &mut Vec<DrawnText>) {
    match item {
        Item::Group(group) => {
            let transform = transform.then(group.transform);
            for child in &group.items {
                text_runs(child, transform, out);
            }
        }
        Item::Text(run) => {
            let bounds = run.bounds();
            out.push(DrawnText {
                text: run_text(run),
                x: transform.e + bounds.x,
                y: transform.f + bounds.y,
                width: run.size.width,
                height: run.size.height,
                baseline: transform.f + bounds.y + run.size.height,
                anchor: anchor_name(run.anchor),
                rotation: transform.b.atan2(transform.a).to_degrees(),
            });
        }
        _ => {}
    }
}

fn texts_in(item: &Item) -> Vec<DrawnText> {
    let mut out = Vec::new();
    text_runs(item, Transform::IDENTITY, &mut out);
    out
}

#[derive(Clone, Debug)]
struct Primitive {
    tag: &'static str,
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    fill: Option<String>,
    stroke: Option<String>,
    stroke_width: f64,
    text: Option<String>,
}

fn color_of(color: &Option<crate::scene::Color>) -> Option<String> {
    color.as_ref().map(|color| color.0.clone())
}

fn icon_primitives(item: &Item) -> Option<(f64, f64, Vec<Primitive>)> {
    fn find(item: &Item) -> Option<&Group> {
        match item {
            Item::Group(group) => {
                if group.class.as_deref() == Some("architecture-icon") {
                    return Some(group);
                }
                group.items.iter().find_map(find)
            }
            _ => None,
        }
    }
    let group = find(item)?;
    let scale = group.transform.a;
    let width = 80.0 * scale;
    let height = 80.0 * group.transform.d;
    let mut primitives = Vec::new();
    for child in &group.items {
        match child {
            Item::Rect(shape) => primitives.push(Primitive {
                tag: "rect",
                x: shape.rect.x,
                y: shape.rect.y,
                width: shape.rect.width,
                height: shape.rect.height,
                fill: color_of(&shape.style.fill),
                stroke: color_of(&shape.style.stroke),
                stroke_width: shape.style.stroke_width,
                text: None,
            }),
            Item::Ellipse(shape) => primitives.push(Primitive {
                tag: "ellipse",
                x: shape.center.x - shape.radius_x,
                y: shape.center.y - shape.radius_y,
                width: shape.radius_x * 2.0,
                height: shape.radius_y * 2.0,
                fill: color_of(&shape.style.fill),
                stroke: color_of(&shape.style.stroke),
                stroke_width: shape.style.stroke_width,
                text: None,
            }),
            Item::Path(shape) => {
                let bounds = crate::render::pipeline::dagre::svg_path_bounds(&shape.path)
                    .unwrap_or(crate::scene::Rect::ZERO);
                primitives.push(Primitive {
                    tag: "path",
                    x: bounds.x,
                    y: bounds.y,
                    width: bounds.width,
                    height: bounds.height,
                    fill: color_of(&shape.style.fill),
                    stroke: color_of(&shape.style.stroke),
                    stroke_width: shape.style.stroke_width,
                    text: None,
                });
            }
            Item::Text(run) => {
                let bounds = run.bounds();
                primitives.push(Primitive {
                    tag: "text",
                    x: bounds.x,
                    y: bounds.y,
                    width: bounds.width,
                    height: bounds.height,
                    fill: color_of(&run.fill),
                    stroke: None,
                    stroke_width: 0.0,
                    text: Some(run_text(run)),
                });
            }
            _ => {}
        }
    }
    Some((width, height, primitives))
}

fn path_points(shape: &PathShape) -> Vec<(f64, f64)> {
    shape
        .path
        .commands
        .iter()
        .filter_map(|command| match *command {
            crate::scene::PathCommand::MoveTo { x, y } => Some((x, y)),
            crate::scene::PathCommand::LineTo { x, y } => Some((x, y)),
            _ => None,
        })
        .collect()
}

/// An arrow polygon: its local points and the translation the edge draws it at.
type ArrowPolygon = (Vec<(f64, f64)>, f64, f64);

fn polygons_in(group: &Group) -> Vec<ArrowPolygon> {
    let mut out = Vec::new();
    for child in &group.items {
        if let Item::Group(arrow) = child
            && let Some(Item::Path(shape)) = arrow.items.first()
            && matches!(
                shape.path.commands.last(),
                Some(crate::scene::PathCommand::Close)
            )
        {
            out.push((path_points(shape), arrow.transform.e, arrow.transform.f));
        }
    }
    out
}

fn compare_text(actual: &DrawnText, expected: &Value, what: &str, file: &str) {
    assert_eq!(
        actual.text,
        expected["text"].as_str().expect("text"),
        "{file}: {what} text"
    );
    close(actual.x, number(expected, "x"), &format!("{what} x"), file);
    close(actual.y, number(expected, "y"), &format!("{what} y"), file);
    close(
        actual.width,
        number(expected, "width"),
        &format!("{what} width"),
        file,
    );
    close(
        actual.height,
        number(expected, "height"),
        &format!("{what} height"),
        file,
    );
    close(
        actual.baseline,
        number(expected, "baseline"),
        &format!("{what} baseline"),
        file,
    );
    assert_eq!(
        actual.anchor,
        expected["anchor"].as_str().expect("anchor"),
        "{file}: {what} anchor"
    );
    close(
        actual.rotation,
        number(expected, "rotation"),
        &format!("{what} rotation"),
        file,
    );
}

fn compare_icon(actual: &(f64, f64, Vec<Primitive>), expected: &Value, what: &str, file: &str) {
    close(
        actual.0,
        number(expected, "width"),
        &format!("{what} width"),
        file,
    );
    close(
        actual.1,
        number(expected, "height"),
        &format!("{what} height"),
        file,
    );
    let primitives = expected["primitives"].as_array().expect("primitives");
    assert_eq!(
        actual.2.len(),
        primitives.len(),
        "{file}: {what} primitive count"
    );
    for (index, (actual, expected)) in actual.2.iter().zip(primitives).enumerate() {
        let what = format!("{what} primitive {index}");
        assert_eq!(
            actual.tag,
            expected["tag"].as_str().expect("tag"),
            "{file}: {what} tag"
        );
        close(actual.x, number(expected, "x"), &format!("{what} x"), file);
        close(actual.y, number(expected, "y"), &format!("{what} y"), file);
        close(
            actual.width,
            number(expected, "width"),
            &format!("{what} width"),
            file,
        );
        close(
            actual.height,
            number(expected, "height"),
            &format!("{what} height"),
            file,
        );
        assert_eq!(
            actual.fill.as_deref(),
            expected["fill"].as_str(),
            "{file}: {what} fill"
        );
        assert_eq!(
            actual.stroke.as_deref(),
            expected["stroke"].as_str(),
            "{file}: {what} stroke"
        );
        close(
            actual.stroke_width,
            number(expected, "strokeWidth"),
            &format!("{what} strokeWidth"),
            file,
        );
        if let Some(text) = expected["text"].as_str() {
            assert_eq!(actual.text.as_deref(), Some(text), "{file}: {what} text");
        }
    }
}

fn child_groups(group: &Group) -> Vec<&Group> {
    group
        .items
        .iter()
        .filter_map(|item| match item {
            Item::Group(group) => Some(group),
            _ => None,
        })
        .collect()
}

#[test]
fn every_fixture_matches_upstream() {
    let fixtures = fixtures();
    assert!(fixtures.len() >= 8, "expected at least 8 fixtures");

    for (file, fixture) in fixtures {
        let source = fixture["source"].as_str().expect("source");
        let expected = &fixture["expected"];
        let config = config_for(source);
        let scene: Scene = render::draw(source, &config, &FallbackMeasure)
            .unwrap_or_else(|error: ArchitectureRenderError| panic!("{file}: {error}"));

        let view_box = &expected["viewBox"];
        close(scene.view_box.x, number(view_box, "x"), "viewBox x", &file);
        close(scene.view_box.y, number(view_box, "y"), "viewBox y", &file);
        close(
            scene.view_box.width,
            number(view_box, "width"),
            "viewBox width",
            &file,
        );
        close(
            scene.view_box.height,
            number(view_box, "height"),
            "viewBox height",
            &file,
        );

        let services_group = scene
            .items
            .iter()
            .find_map(|item| match item {
                Item::Group(group) if group.class.as_deref() == Some("architecture-services") => {
                    Some(group)
                }
                _ => None,
            })
            .expect("the services group");
        let groups_group = scene
            .items
            .iter()
            .find_map(|item| match item {
                Item::Group(group) if group.class.as_deref() == Some("architecture-groups") => {
                    Some(group)
                }
                _ => None,
            })
            .expect("the groups group");
        let edges_group = scene
            .items
            .iter()
            .find_map(|item| match item {
                Item::Group(group) if group.class.as_deref() == Some("architecture-edges") => {
                    Some(group)
                }
                _ => None,
            })
            .expect("the edges group");

        let mut service_index = 0;
        let mut junction_index = 0;
        for child in child_groups(services_group) {
            let x = child.transform.e;
            let y = child.transform.f;
            if child.class.as_deref() == Some("architecture-junction") {
                let expected = &expected["junctions"][junction_index];
                junction_index += 1;
                close(x, number(expected, "x"), "junction x", &file);
                close(y, number(expected, "y"), "junction y", &file);
                let rect = child
                    .items
                    .iter()
                    .find_map(|item| match item {
                        Item::Group(inner) => inner.items.iter().find_map(|item| match item {
                            Item::Rect(rect) => Some(rect),
                            _ => None,
                        }),
                        _ => None,
                    })
                    .expect("the junction rectangle");
                close(
                    rect.rect.width,
                    number(expected, "width"),
                    "junction width",
                    &file,
                );
                close(
                    rect.rect.height,
                    number(expected, "height"),
                    "junction height",
                    &file,
                );
                continue;
            }

            let expected = &expected["services"][service_index];
            service_index += 1;
            assert_eq!(
                expected["id"].as_str(),
                child.source.as_ref().map(|source| source.id.as_str()),
                "{file}: service id"
            );
            close(x, number(expected, "x"), "service x", &file);
            close(y, number(expected, "y"), "service y", &file);

            if !expected["label"].is_null() {
                let expected_label = &expected["label"];
                let expected_text = expected_label["text"].as_str().expect("label text");
                let runs = texts_in(&Item::Group(child.clone()));
                let run = runs
                    .iter()
                    .find(|run| run.text == expected_text)
                    .unwrap_or_else(|| panic!("{file}: service label {expected_text:?}"));
                compare_text(run, expected_label, "service label", &file);
            }
            if let Some(icon) = icon_primitives(&Item::Group(child.clone())) {
                let expected_icon = &expected["icon"];
                assert!(
                    !expected_icon.is_null(),
                    "{file}: an icon is drawn but the fixture has none"
                );
                compare_icon(&icon, expected_icon, "service icon", &file);
            } else {
                assert!(
                    expected["icon"].is_null(),
                    "{file}: the fixture has an icon but the scene has none"
                );
            }
            if !expected["iconText"].is_null() {
                let text = child
                    .items
                    .iter()
                    .find_map(|item| match item {
                        Item::Group(group) => group.items.iter().find_map(|item| match item {
                            Item::Text(run)
                                if run.fill.as_ref().map(|c| c.0.as_str()) == Some("#fff") =>
                            {
                                Some(run_text(run))
                            }
                            _ => None,
                        }),
                        _ => None,
                    })
                    .expect("the icon text");
                assert_eq!(
                    text,
                    expected["iconText"].as_str().expect("iconText"),
                    "{file}: iconText"
                );
            } else {
                assert!(expected["iconText"].is_null(), "{file}: iconText");
            }
            let fallback = child.items.iter().any(|item| matches!(item, Item::Path(_)));
            assert_eq!(
                fallback,
                !expected["fallback"].is_null(),
                "{file}: fallback node background"
            );
        }
        assert_eq!(
            service_index,
            expected["services"].as_array().expect("services").len(),
            "{file}: service count"
        );
        assert_eq!(
            junction_index,
            expected["junctions"].as_array().expect("junctions").len(),
            "{file}: junction count"
        );

        let mut group_rects = 0;
        let mut group_labels = 0;
        for item in &groups_group.items {
            match item {
                Item::Rect(rect) => {
                    let expected = &expected["groups"][group_rects];
                    group_rects += 1;
                    close(rect.rect.x, number(expected, "x"), "group x", &file);
                    close(rect.rect.y, number(expected, "y"), "group y", &file);
                    close(
                        rect.rect.width,
                        number(expected, "width"),
                        "group width",
                        &file,
                    );
                    close(
                        rect.rect.height,
                        number(expected, "height"),
                        "group height",
                        &file,
                    );
                }
                Item::Group(label_container) => {
                    let expected = &expected["groups"][group_labels];
                    group_labels += 1;
                    if !expected["label"].is_null() {
                        let runs = texts_in(&Item::Group(label_container.clone()));
                        assert_eq!(runs.len(), 1, "{file}: group label runs");
                        compare_text(&runs[0], &expected["label"], "group label", &file);
                    }
                    if let Some(icon) = icon_primitives(&Item::Group(label_container.clone())) {
                        compare_icon(&icon, &expected["icon"], "group icon", &file);
                    } else {
                        assert!(
                            expected["icon"].is_null(),
                            "{file}: the fixture has a group icon but the scene has none"
                        );
                    }
                }
                _ => {}
            }
        }
        assert_eq!(
            group_rects,
            expected["groups"].as_array().expect("groups").len(),
            "{file}: group count"
        );

        let edge_groups = child_groups(edges_group);
        let expected_edges = expected["edges"].as_array().expect("edges");
        assert_eq!(
            edge_groups.len(),
            expected_edges.len(),
            "{file}: edge count"
        );
        for (index, (edge, expected)) in edge_groups.iter().zip(expected_edges).enumerate() {
            let path = edge
                .items
                .iter()
                .find_map(|item| match item {
                    Item::Path(shape) => Some(shape),
                    _ => None,
                })
                .expect("the edge path");
            let points = path_points(path);
            let expected_points = expected["points"].as_array().expect("points");
            assert_eq!(
                points.len(),
                expected_points.len(),
                "{file}: edge {index} point count"
            );
            for (point, expected_point) in points.iter().zip(expected_points) {
                close(point.0, number(expected_point, "x"), "edge point x", &file);
                close(point.1, number(expected_point, "y"), "edge point y", &file);
            }

            let arrows = polygons_in(edge);
            let expected_arrows = expected["arrows"].as_array().expect("arrows");
            assert_eq!(
                arrows.len(),
                expected_arrows.len(),
                "{file}: edge {index} arrow count"
            );
            for (arrow, expected_arrow) in arrows.iter().zip(expected_arrows) {
                let expected_points = expected_arrow["points"].as_array().expect("arrow points");
                assert_eq!(arrow.0.len(), expected_points.len(), "{file}: arrow points");
                for (point, expected_point) in arrow.0.iter().zip(expected_points) {
                    close(point.0, number(expected_point, "x"), "arrow x", &file);
                    close(point.1, number(expected_point, "y"), "arrow y", &file);
                }
                close(
                    arrow.1,
                    number(&expected_arrow["translate"], "x"),
                    "arrow translate x",
                    &file,
                );
                close(
                    arrow.2,
                    number(&expected_arrow["translate"], "y"),
                    "arrow translate y",
                    &file,
                );
            }

            if !expected["label"].is_null() {
                let runs = texts_in(&Item::Group((*edge).clone()));
                let expected_label = &expected["label"];
                let run = runs
                    .iter()
                    .find(|run| run.text == expected_label["text"].as_str().unwrap_or_default())
                    .unwrap_or_else(|| panic!("{file}: edge {index} label"));
                compare_text(run, expected_label, "edge label", &file);
            }
        }
    }
}

#[test]
fn the_dispatch_draws_an_architecture_diagram() {
    let source =
        "architecture-beta\n  service a(server)[A]\n  service b(database)[B]\n  a:R -- L:b\n";
    let config = Config::default();
    let dispatched = crate::render_diagram(source, &config).expect("render through the dispatch");
    let direct = render::render(
        &crate::preprocess::preprocess(source).body,
        &config_for(source),
    )
    .expect("render architecture");
    assert_eq!(dispatched, direct);
}

#[test]
fn the_theme_paints_edges_and_group_borders() {
    let source = "architecture-beta\n  group g(cloud)[G]\n  service a(server)[A] in g\n  service b(database)[B] in g\n  a:R -- L:b\n";
    let scene = render::render(source, &Config::default()).expect("render");
    let groups = scene
        .items
        .iter()
        .find_map(|item| match item {
            Item::Group(group) if group.class.as_deref() == Some("architecture-groups") => {
                Some(group)
            }
            _ => None,
        })
        .expect("groups");
    let rect = groups
        .items
        .iter()
        .find_map(|item| match item {
            Item::Rect(rect) => Some(rect),
            _ => None,
        })
        .expect("a group rectangle");
    assert_eq!(
        rect.style.stroke.as_ref().map(|c| c.0.as_str()),
        Some("hsl(240, 60%, 86.2745098039%)")
    );
    assert_eq!(rect.style.stroke_width, 2.0);
    assert_eq!(rect.style.dash, vec![8.0]);

    let edges = scene
        .items
        .iter()
        .find_map(|item| match item {
            Item::Group(group) if group.class.as_deref() == Some("architecture-edges") => {
                Some(group)
            }
            _ => None,
        })
        .expect("edges");
    let path = edges
        .items
        .iter()
        .find_map(|item| match item {
            Item::Group(edge) => edge.items.iter().find_map(|item| match item {
                Item::Path(shape) => Some(shape),
                _ => None,
            }),
            _ => None,
        })
        .expect("an edge path");
    assert_eq!(
        path.style.stroke.as_ref().map(|color| color.0.as_str()),
        Some("#333333")
    );
    assert_eq!(path.style.stroke_width, 3.0);
}
